def brand_logo(slug: str, size: int = 20) -> Markup:
    """Decorative: the platform's name is always written beside it."""
    _, path = LOGOS[slug]
    return Markup(
        f'<svg class="brand-logo" width="{size}" height="{size}" viewBox="0 0 24 24" fill="currentColor"'
        f' aria-hidden="true"><path d="{path}"/></svg>'
    )
